indirect enum Expr {
    case num(Double)
    case add(Expr, Expr)
}

func evaluate(_ e: Expr) -> Double {          // one operation
    switch e {
    case .num(let v):        return v
    case .add(let l, let r): return evaluate(l) + evaluate(r)
    }
}

